@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Stats Bar -->
    <div class="row mb-3">
        <div class="col">
            <div class="d-flex gap-3 p-2 bg-light rounded">
                <span><strong>Total:</strong> @_filteredTasks.Count</span>
                <span><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
                <span><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
                <span><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
                <span><strong>Overdue:</strong> @_filteredTasks.Count(t => t.DueDate < DateTime.Today)</span>
            </div>
        </div>
    </div>

    <!-- Search Bar -->
    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Search tasks by title..."
                   @bind="_searchText" @bind:event="oninput" />
        </div>
    </div>

    <!-- Kanban Columns -->
    <div class="row">
        @foreach (var column in _columns)
        {
            var columnTasks = GetColumnTasks(column);
            var colIndex = Array.IndexOf(_columns, column);
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@column</strong>
                        <span class="badge bg-secondary">@columnTasks.Count</span>
                    </div>
                    <div class="card-body">
                        @foreach (var task in columnTasks)
                        {
                            <div class="card mb-2">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="card-text mb-1"><small>@task.Assignee</small></p>
                                    <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                    <small class="ms-2">@task.DueDate.ToString("MMM dd")</small>
                                    <div class="mt-2">
                                        @if (colIndex > 0)
                                        {
                                            <button class="btn btn-sm btn-outline-secondary me-1"
                                                    @onclick="() => MoveTask(task.Id, _columns[colIndex - 1])">
                                                &larr; Move Left
                                            </button>
                                        }
                                        @if (colIndex < _columns.Length - 1)
                                        {
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    @onclick="() => MoveTask(task.Id, _columns[colIndex + 1])">
                                                Move Right &rarr;
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (_showForm == column)
                        {
                            <div class="card mb-2 border-primary">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Title" @bind="_newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Assignee" @bind="_newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-1"
                                           @bind="_newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-sm btn-primary"
                                                @onclick="() => SaveTask(column)">Save</button>
                                        <button class="btn btn-sm btn-secondary"
                                                @onclick="CancelForm">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                        else
                        {
                            <button class="btn btn-sm btn-outline-primary w-100"
                                    @onclick="() => ShowAddForm(column)">+ Add Task</button>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = { "To Do", "In Progress", "Done" };
    private List<TaskItem> _allTasks = new();
    private List<TaskItem> _filteredTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchText = string.Empty;

    // Add form state
    private string? _showForm;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);

    private string SearchText
    {
        get => _searchText;
        set
        {
            _searchText = value;
            ApplyFilter();
        }
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
            ApplyFilter();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private void ApplyFilter()
    {
        _filteredTasks = string.IsNullOrWhiteSpace(_searchText)
            ? _allTasks.ToList()
            : _allTasks.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        _filteredTasks.Where(t => t.Status == status).ToList();

    private string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _allTasks.FirstOrDefault(t => t.Id == taskId);
            if (task is not null)
            {
                var index = _allTasks.IndexOf(task);
                _allTasks[index] = task with { Status = newStatus };
                ApplyFilter();
            }
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private void ShowAddForm(string column)
    {
        _showForm = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelForm() => _showForm = null;

    private async Task SaveTask(string column)
    {
        if (string.IsNullOrWhiteSpace(_newTitle))
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
            // The service creates with default status; update to target column if needed
            if (created.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, column);
                created = created with { Status = column };
            }
            _allTasks.Add(created);
            ApplyFilter();
            _showForm = null;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }
}

